def _zip_filename_and_flags(name: bytes, flags: int) -> tuple[str | None, str | None]:
    """Accept the stdlib writer's ASCII flag 0 and non-ASCII UTF-8 flag 0x0800 only."""
    if flags & ~ZIP_UTF8_FLAG:
